export class Order {
  #lines = [];
  constructor(customerId) { this.customerId = customerId; }
  get total() { return this.#lines.reduce((sum, l) => sum + l.price, 0); }
  addLine(line) {
    if (this.total + line.price > LIMIT) throw new OrderLimitExceeded();
    this.#lines.push(line);
  }
}
// factory (JS has no private constructor):
export const openOrder = (customerId) => new Order(customerId);
